-- jobs (4)
INSERT OR IGNORE INTO jobs (id, title, source, raw_brief, client_price_micros, deadline_at, status, client_id, client_notes, template_id, source_fee_bps, contingency_bps, target_margin_bps, max_production_micros, recording_gate, created_at, updated_at) VALUES ('job_rain', 'After the Rain: Glass Monument', 'Upwork (pasted)', 'Title: After the Rain: Glass Monument

Pasted from an Upwork message. Do not contact the marketplace. The client is now on our direct thread.

We need a short cinematic concept film of a civic glass monument that appears after a storm. This is not a product ad and not a talking-head video.

Deliverables
- One 12-second film, 16:9
- The same film in 9:16, 12 seconds
- Three approved keyframe stills, 16:9

Fixed package: $2,800
Deadline: 72 hours from kickoff

Supplied
- Approved monument silhouette (elevation)
- Glass material references: ribbed cast and smoked sheet. We still need to confirm which is final.
- Site direction: river terrace, low city behind, no identifiable private buildings
- Weather arc: hard rain, break in the cloud, low sun on wet stone
- Liked: quiet monumental scale, physically believable water
- Disliked: fantasy crystal, neon, people in frame, readable signage

Constraints
- The monument''s architecture, material, scale, and site stay consistent across shots
- Water, reflections, and the transition after the storm stay believable
- No people, no logos, no exact packaging text, no licensed music
- Original score is out of scope. Native ambience or silence is fine.

Please confirm the glass sample before final motion.', 2800000000, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '+129600 seconds'), 'qa', 'client_northline', 'Client confirmed the smoked sheet after the intake question. Included revisions: 2.', 'launch-video', 1000, 2000, 5500, 40000000, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-86400 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-3600 seconds'));
INSERT OR IGNORE INTO jobs (id, title, source, raw_brief, client_price_micros, deadline_at, status, client_id, client_notes, template_id, source_fee_bps, contingency_bps, target_margin_bps, max_production_micros, recording_gate, created_at, updated_at) VALUES ('job_orchard', 'Night Orchard: Slow Orbit', 'Sales call (pasted)', 'Title: Night Orchard: Slow Orbit

Pasted from a sales-call note.

Deliverable
- One atmospheric short sequence, 8 seconds, 16:9, built around a smooth orbiting camera move
- One hero still

Supplied
- Approved orchard-world keyframe
- Low-light palette: sodium green, wet bark, no moonlight hotspot
- Camera direction: slow 30-degree orbit, no whip pans
- Pacing reference: hold, drift, settle
- No captions, no voice, no people, no text

Constraints
- Preserve the world, depth, low-light detail, and spatial continuity throughout the orbit
- We accept 720p if that is the ceiling of the reference-preserving model you can price today

Fixed package: $900
Deadline: 48 hours', 900000000, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '+172800 seconds'), 'needs_review', 'client_hollow', 'Different problem from the monument film: one orbit, one still, low light.', NULL, 0, 2000, 5500, 15000000, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-20000 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-2000 seconds'));
INSERT OR IGNORE INTO jobs (id, title, source, raw_brief, client_price_micros, deadline_at, status, client_id, client_notes, template_id, source_fee_bps, contingency_bps, target_margin_bps, max_production_micros, recording_gate, created_at, updated_at) VALUES ('job_reject', 'Rejected fixture — celebrity voice clone', 'Direct form (pasted)', 'Need a 15-second ad. Make a famous singer appear to endorse our canned drink and say the slogan in their real voice. Pull the likeness from a public interview. Budget $500. Need it tomorrow.', 500000000, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '+72000 seconds'), 'rejected', 'client_reject', 'Policy fixture. Deceptive impersonation is rejected.', NULL, 1000, 2000, 5500, 40000000, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-10000 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-9000 seconds'));
INSERT OR IGNORE INTO jobs (id, title, source, raw_brief, client_price_micros, deadline_at, status, client_id, client_notes, template_id, source_fee_bps, contingency_bps, target_margin_bps, max_production_micros, recording_gate, created_at, updated_at) VALUES ('job_new', 'Email — seasonal stills inquiry', 'Email', 'Email from Priya Raman.

We may want three seasonal stills for a ceramic pour-over next month. No brief yet, no logo, no deadline. Please wait for the product photos before anyone starts.', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '+1814400 seconds'), 'new', 'client_priya', 'Waiting on product photos. Not analyzed.', NULL, 0, 2000, 5500, 10000000, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1000 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1000 seconds'));

