INSERT OR IGNORE INTO workflows (id, job_id, status, steps_json, approved_max_micros, created_at, updated_at) VALUES ('wf_rain', 'job_rain', 'approved', '[{"id":"concepts","order":1,"role":"search","capability":"Inexpensive cinematic still exploration","purpose":"Generate 8 monument-and-weather concepts and discard the ones that drift.","modelId":"higgsfield-ai/soul/v2/standard","why":"Soul 2 is the lowest published image rate and is documented for editorial stills. Eight frames is two batches of four.","failureMode":"Architecture and glass color can wander. These frames are not client-facing.","alternativeModelId":"marketing-studio/image","alternativeNote":"Marketing Studio Image is the control alternative if concepts need a product-style lock earlier.","attempts":1,"quantity":8,"inputs":"Monument silhouette description, weather arc, disliked references.","expectedOutputs":"Eight 16:9 concept stills.","settings":{"resolution":"720p","aspect_ratio":"16:9","batch_size":4,"enhance_prompt":false},"conditional":false,"modelName":"Soul 2","alternativeName":"Marketing Studio Image","unit":"image","unitCostMicros":3200,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":25600,"maxAuthorizedMicros":25600},{"id":"keyframes","order":2,"role":"control","capability":"Controlled keyframes for material, scale, and site","purpose":"Lock three keyframes: downpour, cloud break, and low sun on wet stone.","modelId":"marketing-studio/image","why":"Marketing Studio Image accepts reference images and is the documented product/reference control lane.","failureMode":"Glass can look like plastic if the reference URLs are weak. Unenhanced auto aspect maps toward square, so aspect is set explicitly.","alternativeModelId":"alibaba/qwen-image-3/edit","alternativeNote":"Qwen Image 3 Edit is the correction tool if a keyframe needs a local material fix.","attempts":1,"quantity":3,"inputs":"Chosen concept, monument silhouette, glass reference, site direction.","expectedOutputs":"Three approved 16:9 keyframes.","settings":{"resolution":"2k","aspect_ratio":"16:9","quality":"high","enhance_prompt":false},"conditional":false,"modelName":"Marketing Studio Image","alternativeName":"Qwen Image 3 Edit","unit":"image","unitCostMicros":5900,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":17700,"maxAuthorizedMicros":17700},{"id":"film-169","order":3,"role":"ship","capability":"Premium final motion, 16:9","purpose":"Animate the approved keyframe into a 12-second cinematic film with believable rain and reflections.","modelId":"kling-video/v3.0/pro/image-to-video","why":"Kling 3.0 Pro image-to-video is the premium motion lane: first frame in, native audio, multi-shot support.","failureMode":"Water, reflections, and rigid architecture can break between shots. Resolution is not a request field on this endpoint.","alternativeModelId":"bytedance/seedance-2.5/image-to-video","alternativeNote":"Seedance 2.5 is cheaper per second and preserves a start frame, but its documented max is 720p.","attempts":2,"quantity":12,"inputs":"Approved reveal keyframe and the weather-arc prompt.","expectedOutputs":"One 12-second 16:9 film.","settings":{"duration":12,"aspect_ratio":"16:9","sound":"on","qaScript":"reflection_continuity"},"conditional":false,"modelName":"Kling 3.0 Pro Image to Video","alternativeName":"Seedance 2.5 Image to Video","unit":"second","unitCostMicros":112000,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number. Applied as the published Kling 3.0 family rate. Pro vs Standard is not split in that table.","estimatedTotalMicros":2688000,"maxAuthorizedMicros":2688000},{"id":"film-916","order":4,"role":"ship","capability":"Premium final motion, 9:16","purpose":"Reframe the same locked monument into a 12-second vertical film without changing architecture.","modelId":"kling-video/v3.0/pro/image-to-video","why":"The same premium lane keeps camera language consistent across the two deliveries.","failureMode":"Vertical reframes can crop the site or scale the monument. Treat a crop change as a failed component, not a new film.","alternativeModelId":"bytedance/seedance-2.5/image-to-video","alternativeNote":"Use Seedance only if the vertical pass is a single locked move and 720p is acceptable.","attempts":2,"quantity":12,"inputs":"Same keyframe, 9:16 safe-area note.","expectedOutputs":"One 12-second 9:16 film.","settings":{"duration":12,"aspect_ratio":"9:16","sound":"on"},"conditional":false,"modelName":"Kling 3.0 Pro Image to Video","alternativeName":"Seedance 2.5 Image to Video","unit":"second","unitCostMicros":112000,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number. Applied as the published Kling 3.0 family rate. Pro vs Standard is not split in that table.","estimatedTotalMicros":2688000,"maxAuthorizedMicros":2688000},{"id":"repair","order":5,"role":"finish","capability":"Targeted continuity repair","purpose":"Repair one reflection or geometry failure without rerunning both films.","modelId":"bytedance/seedance-2.5/video-edit","why":"Seedance 2.5 video-edit takes the finished shot and a prompt. Docs say not to send duration; cost uses the 12-second source.","failureMode":"The edit can warm or cool the grade while fixing the reflection.","alternativeModelId":"kling-video/o3/video-edit","alternativeNote":"Kling O3 video edit is documented, but it has no published rate, so it cannot be pre-authorized.","attempts":1,"quantity":12,"inputs":"The failed film and a one-sentence repair note.","expectedOutputs":"One repaired film matching the source frame.","settings":{"derivedDuration":true},"conditional":true,"modelName":"Seedance 2.5 Video Edit","alternativeName":"Kling O3 Video Edit","unit":"second","unitCostMicros":73800,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number. The table does not split edit from generate. Duration is derived from the source video; do not send duration.","estimatedTotalMicros":885600,"maxAuthorizedMicros":885600},{"id":"grade-stills","order":6,"role":"finish","capability":"Finish the three keyframes","purpose":"Grade the approved stills so they match the film without adding people, logos, or type.","modelId":"higgsfield-ai/soul/cinema","why":"Soul Cinema is the documented graded-still finisher at the same published rate as Soul 2.","failureMode":"It is text-to-image with a fixed style, so it is a grade reference, not a pixel lock. Qwen edit is the override if the still must match exactly.","alternativeModelId":"alibaba/qwen-image-3/edit","alternativeNote":"Switch to Qwen when the still has to keep the keyframe and only change grade.","attempts":1,"quantity":3,"inputs":"Approved keyframe descriptions.","expectedOutputs":"Three finished stills.","settings":{"resolution":"720p","aspect_ratio":"16:9","batch_size":1,"enhance_prompt":false},"conditional":false,"modelName":"Soul Cinema","alternativeName":"Qwen Image 3 Edit","unit":"image","unitCostMicros":3200,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":9600,"maxAuthorizedMicros":9600}]', 40000000, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-69000 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-20000 seconds'));
INSERT OR IGNORE INTO workflows (id, job_id, status, steps_json, approved_max_micros, created_at, updated_at) VALUES ('wf_orchard', 'job_orchard', 'draft', '[{"id":"orbit-studies","order":1,"role":"search","capability":"Fast orbit studies","purpose":"Test pacing with two 5-second orbit studies before touching the approved world.","modelId":"pixverse/v6/text-to-video","why":"PixVerse V6 has a published per-second rate and a 1–15 second duration, so short studies stay cheap.","failureMode":"These studies will not match the orchard. They only answer whether the move is slow enough.","alternativeModelId":"lightricks/ltx-2.5/text-to-video/fast","alternativeNote":"LTX 2.5 Fast is the other documented fast lane, but its rate is unpublished so it stays an alternative.","attempts":2,"quantity":5,"inputs":"Camera note: slow 30-degree orbit, no whip pan.","expectedOutputs":"Two disposable 5-second motion studies.","settings":{"duration":5,"resolution":"720p","aspect_ratio":"16:9"},"conditional":false,"modelName":"PixVerse V6 Text to Video","alternativeName":"LTX 2.5 Fast Text to Video","unit":"second","unitCostMicros":115000,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":1150000,"maxAuthorizedMicros":1150000},{"id":"palette-lock","order":2,"role":"control","capability":"Low-light palette lock on the approved keyframe","purpose":"Edit the supplied orchard keyframe toward sodium green and wet bark without moving the trees.","modelId":"alibaba/qwen-image-3/edit","why":"Qwen Image 3 Edit is the documented still-edit model and requires the reference image.","failureMode":"Edits can repaint foliage. The prompt has to say what must not change.","alternativeModelId":"marketing-studio/image","alternativeNote":"Marketing Studio can take reference URLs, but it is aimed at product shots more than night landscapes.","attempts":2,"quantity":1,"inputs":"Approved orchard keyframe.","expectedOutputs":"One controlled hero still.","settings":{"resolution":"1k","aspect_ratio":"16:9"},"conditional":false,"modelName":"Qwen Image 3 Edit","alternativeName":"Marketing Studio Image","unit":"image","unitCostMicros":30000,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":60000,"maxAuthorizedMicros":60000},{"id":"orbit","order":3,"role":"ship","capability":"Smooth orbit from the locked still","purpose":"Generate an 8-second orbit that keeps world, depth, and spatial continuity.","modelId":"bytedance/seedance-2.5/image-to-video","why":"Seedance 2.5 image-to-video starts from image_url, which is the continuity requirement. 720p is the documented maximum on this endpoint, and the brief was qualified to that.","failureMode":"Low-light detail can crush. A 1080p master is not available on this endpoint.","alternativeModelId":"kling-video/v3.0/pro/image-to-video","alternativeNote":"Kling Pro is the cinematic alternative if the move needs harder camera drama. It costs more per second and does not expose resolution.","attempts":2,"quantity":8,"inputs":"Palette-locked hero still and the orbit direction.","expectedOutputs":"One 8-second 16:9 orbit at 720p.","settings":{"duration":8,"resolution":"720p","bitrate_mode":"high","generate_audio":true},"conditional":false,"modelName":"Seedance 2.5 Image to Video","alternativeName":"Kling 3.0 Pro Image to Video","unit":"second","unitCostMicros":73800,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number.","estimatedTotalMicros":1180800,"maxAuthorizedMicros":1180800},{"id":"orbit-repair","order":4,"role":"finish","capability":"Continuity repair if the orbit breaks","purpose":"Patch a single spatial or low-light failure on the orbit. No upscaler is available in the current catalog.","modelId":"bytedance/seedance-2.5/video-edit","why":"The same family can edit the shot it generated. Topaz and other upscalers are not in the current docs index.","failureMode":"Editing can disturb the orbit''s speed.","alternativeModelId":"kling-video/o3/video-edit","alternativeNote":"Kling O3 edit has no published rate, so it is visible but not authorized.","attempts":1,"quantity":8,"inputs":"The orbit and the failed-component note.","expectedOutputs":"One repaired 8-second orbit, or an escalation if the cap is exceeded.","settings":{"derivedDuration":true},"conditional":true,"modelName":"Seedance 2.5 Video Edit","alternativeName":"Kling O3 Video Edit","unit":"second","unitCostMicros":73800,"priceKnown":true,"priceNote":"Higgsfield, “How To Generate AI Videos Straight From the Higgsfield API” (2026-09-16), representative family list rate. Live POST /estimate/{endpoint} overrides this number. The table does not split edit from generate. Duration is derived from the source video; do not send duration.","estimatedTotalMicros":590400,"maxAuthorizedMicros":590400}]', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-19000 seconds'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-19000 seconds'));

