INSERT OR IGNORE INTO messages (id, job_id, payload_json, created_at) VALUES ('msg_q', 'job_rain', '{"kind":"intake_question","channel":"first_party_portal","audience":"client","status":"sent","subject":"Which glass is the monument?","body":"Which glass reference is approved for the monument skin — the ribbed cast sample or the smoked sheet? Everything else can wait.","reason":"Human approved this question. It was the one missing input that changes the film.","createdAt":"2026-09-30T17:33:04.319Z"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-75000 seconds'));
INSERT OR IGNORE INTO messages (id, job_id, payload_json, created_at) VALUES ('msg_progress', 'job_rain', '{"kind":"progress","channel":"first_party_portal","audience":"client","status":"sent","subject":"Keyframes are ready","body":"Three keyframes are up for a look: downpour, cloud break, and low sun on wet stone. The smoked sheet is locked. No decision is needed unless the site feels wrong.","reason":"Human approved a milestone note after the keyframes completed.","createdAt":"2026-09-30T20:19:44.322Z"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-65000 seconds'));
INSERT OR IGNORE INTO messages (id, job_id, payload_json, created_at) VALUES ('msg_concept', 'job_rain', '{"kind":"concept","channel":"first_party_portal","audience":"client","status":"sent","subject":"Two directions from the batch","body":"Eight concepts came back. We kept the two that hold the silhouette and threw out the crystal-looking ones. The next spend is the 12-second motion pass.","reason":"Concepts were shared after approval. Auto-share is off.","createdAt":"2026-09-30T23:06:24.324Z"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-55000 seconds'));
INSERT OR IGNORE INTO messages (id, job_id, payload_json, created_at) VALUES ('msg_delivery', 'job_rain', '{"kind":"delivery","channel":"first_party_portal","audience":"client","status":"draft","subject":"Delivery is ready for your approval","body":"The 16:9 film, the 9:16 film, and three stills are in the package. A reflection repair is in the 16:9 cut. Final delivery has not been sent.","reason":"Final delivery requires approval.","createdAt":"2026-10-01T01:53:04.325Z"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-45000 seconds'));

